xml_escape<-function(s){s<-gsub('&','&amp;',s,fixed=TRUE);s<-gsub('<','&lt;',s,fixed=TRUE);gsub('>','&gt;',s,fixed=TRUE)}
word<-function(lines,out,images=FALSE){doc<-read_docx();doc<-body_set_default_section(doc,prop_section(page_size=page_size(width=8.27,height=11.69),page_margins=page_mar(top=.7,bottom=.7,left=.75,right=.75)));for(line in lines){if(!nzchar(line))next;if(grepl('^EQUATION:',line)){txt<-sub('^EQUATION: ','',line);doc<-body_add_xml(doc,paste0('<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"><m:oMathPara><m:oMath><m:r><m:t>',xml_escape(txt),'</m:t></m:r></m:oMath></m:oMathPara></w:p>'))}else if(grepl('^### ',line))doc<-body_add_par(doc,sub('^### ','',line),style='heading 2')else if(grepl('^##? ',line))doc<-body_add_par(doc,sub('^##? ','',line),style='heading 1')else doc<-body_add_fpar(doc,fpar(ftext(line,fp_text(font.family='Arial',font.size=11))),style='Normal')};if(images){a4<-prop_section(page_size=page_size(width=8.27,height=11.69),type='nextPage');doc<-body_end_block_section(doc,block_section(a4));doc<-body_set_default_section(doc,prop_section(page_size=page_size(width=11.69,height=16.54),page_margins=page_mar(top=.5,bottom=.5,left=.5,right=.5)));for(i in 1:4){doc<-body_add_break(doc);doc<-body_add_par(doc,paste('Figure',i),style='heading 1');doc<-body_add_img(doc,path('figures/main',paste0('Figure',i,'.png')),width=7.2,height=250/25.4);doc<-body_add_par(doc,paste(mainleg[[i]],collapse=' '))}};print(doc,target=out)}

figtitles<-c(Figure1='Regional SSB organization and cohort-relative yield',Figure2='Disease-associated features and direct pathology comparisons',Figure3='Transcript architecture and GENE-sensitivity functional context',Figure4='Representative EXON signals, internal discrimination and clinical relationships')
mainleg<-lapply(names(contract$main),function(n){ids<-contract$main[[n]];tags<-if(n=='Figure4')c('A1','A2','A3','B','C','D1','D2','E','F','G','H')else LETTERS[seq_along(ids)];c(paste0(n,' | ',figtitles[n],'.'),paste(vapply(seq_along(ids),function(i)paste0(tags[i],', ',contract$captions[[ids[i]]]$en),character(1)),collapse=' '))});names(mainleg)<-names(contract$main)
mainleg$Figure1<-c('Figure 1 | Regional organization of blood SSBs in the three research groups.',sprintf('A, Fractions of complete-library SSB positions overlapping globally nonredundant EXON, GENE, INTRON and TSS200 annotations. HC, n=144; AD, n=89; Other, n=28. AD denotes reviewed Core 1-positive pathology and Other Core 1-negative cognitive disorders. Classes can overlap and fractions do not sum to one. B–E, GENE, TSS200, INTRON and EXON Ri, respectively, using the same unfiltered cohort GENE reference (B=%.9f). Boxes show median and IQR; whiskers extend to observations within 1.5 IQR; every point represents a participant. Brackets show nominal two-sided pairwise Wilcoxon P. F, GENE Ri versus complete-library deduplicated position yield; the two-sided Spearman test uses all261 participants. G, Three-group adjusted log2(Ri+1) effects and95%% CI for the12 predefined regional contrasts (HC142, AD89, Other28; total259). Models include age, sex, log10 library yield and poly(A)-filter retention. H, Observed ages (HC143, AD89, Other28); one HC age was unavailable. Full adjusted P values and actual sample lists are in the source data.',B))
mainleg$Figure2<-c('Figure 2 | Region-resolved disease associations and pathology comparisons.','A–D, GENE, TSS200, INTRON and EXON combined-disease versus HC associations (n=259). EXON is primary, GENE sensitivity, and the other spaces complementary. Horizontal axes show adjusted log2(1+SSB_LPKM) differences; vertical axes show nominal P. Colors identify higher or lower features passing within-region BH correction; the dashed nominal P=0.05 line is not the corrected selection rule. E, Primary EXON sets significant in the AD–HC or Other–HC contrasts; shared requires significance and concordant direction in both. F, Higher and lower counts for all three predefined contrasts in each region. G, EXON effects against HC for the two pathology groups; the diagonal is a reference, not an equivalence test. H, Direction and corrected-association retention after removing cross-gene shared intervals. I, Retention among common tested primary associations under blood-cell adjustment (n=159) and10%/30% detection thresholds (n=259). Cell percentages show direction agreement/association retention; population changes and correction are documented in source tables. Significance against HC in one group but not another does not establish a direct pathology difference.')
mainleg$Figure3<-c('Figure 3 | Transcript architecture and whole-gene sensitivity functional context.','A, Mean profile Ri across the13 original transcript-oriented structural classes and150 bins (HC144; AD plus Other117). The curve uses exact participant-level annotation-summed counts and the common GENE reference. Shading denotes pointwise95% percentile intervals from2,000 participant resamples. Internal exon/intron classes are standardized concatenated transcript structures; annotation multiplicity is retained. B, GENE-sensitivity enrichment support after2,000 annotation-length-stratified draws: supported/returned terms within each complete provider-returned category. C–F, GO biological process, GO cellular component, Reactome and HPO, respectively, for the independently labeled GENE sensitivity set. Up to five provider-corrected terms per category are shown; horizontal axes use nominal P and point size encodes overlapping proteins. Background consists of actually tested mapped genes. HPO indicates database annotations, not measured patient phenotypes. Primary EXON enrichment did not pass the prespecified categories and is reported in Supplementary Fig.S12. Exposure-normalized profiles and complete region/bin comparisons are supplied separately.')
mainleg$Figure4<-c('Figure 4 | Representative EXON features, internal discrimination and clinical relationships.','A1–A3, CHKB-DT, RHBDF1 and TBC1D20 EXON log2(1+SSB_LPKM) values in HC144, AD89 and Other28. Features were ranked in the pooled primary cohort; they were not a full-cohort prefilter for prediction. Boxes show median/IQR,1.5IQR whiskers and all participants. Brackets are nominal adjusted limma contrast P (model n=259). B, Independently trained regional source-model ROC curves (HC142 versus combined disease117). C, Independently trained AD–Other ROC curves (89 versus28). Probabilities are per-participant averages of five outer-held-out predictions from fivefold nested validation repeated five times, with fourfold inner tuning. D1, Pathology precision–recall curves with the observed AD fraction89/117 as reference. D2, Five repetition-specific AUCs; repetitions are not independent biological replicates. E, Primary EXON source score versus concurrent observed MMSE in disease participants (n=100; Spearman test). F, Four adjusted MMSE effects per0.1 source probability, with95% CI (n=100 each). G, Predefined observed clinical correlations; each row displays actual paired n, cell text nominal Spearman P, and color rho. H, Internal source-model calibration and Brier scores; exact bin sizes are supplied. All preprocessing and selection were fitted within training folds. Bootstrap AUC intervals are conditional on the existing held-out predictions, not external validation.')
legend_en<-c('# Figure legends',unlist(lapply(mainleg,function(z)c(paste0('## ',z[1]),z[2]))));legend_zh<-c('# 主图图注',unlist(lapply(names(contract$main),function(n)c(paste0('## ',n),paste(vapply(contract$main[[n]],function(id)paste0(id,'：',contract$captions[[id]]$zh),character(1)),collapse=' ')))))
supp_en<-c('# Supplementary figure legends',unlist(lapply(names(contract$supplementary_layout),function(n){ids<-contract$supplementary_layout[[n]];c(paste0('## Supplementary Figure ',n),paste(vapply(seq_along(ids),function(i)paste0(LETTERS[i],', ',contract$captions[[ids[i]]]$en),character(1)),collapse=' '))})))
supp_zh<-c('# 补充图图注',unlist(lapply(names(contract$supplementary_layout),function(n){ids<-contract$supplementary_layout[[n]];c(paste0('## Supplementary Figure ',n),paste(vapply(seq_along(ids),function(i)paste0(LETTERS[i],'：',contract$captions[[ids[i]]]$zh),character(1)),collapse=' '))})))
for(item in list(list(legend_en,'Figure_legends_EN'),list(legend_zh,'Figure_legends_ZH'),list(supp_en,'Supplementary_figure_legends_EN'),list(supp_zh,'Supplementary_figure_legends_ZH'))){writeLines(item[[1]],path('manuscript',paste0(item[[2]],'.md')));word(item[[1]],path('manuscript',paste0(item[[2]],'.docx')))}
